cir.nfmodel:
.param vth0=3.5
.func softplus(x) {ln(1+exp(x))}
.subckt BEHAV_FET d g s params: kp=8 lam=0.01
.param vt={vth0+0.3} rgate={2*1}
Rg g gi {rgate}
Cgs gi s 1.5n
Cgd gi d 0.3n
G1 d s VALUE={kp*pwr(0.1*softplus((V(gi,s)-vt)/0.1),2)*(1+lam*V(d,s))*tanh(V(d,s)/0.5)}
Dbody s d DB
.model DB D(Is=1e-12 N=1.1 Rs=10m Cjo={0.5n} TT=50n)
.ends
